<script setup lang="ts">
import {onMounted,watch} from 'vue';
import {t,formatDate,formatAmount} from '@kuaixie/i18n';
import {useTradeCases,caseTypes,caseResolutions,caseTypeKey,caseOutcomeKey,caseStageKey,caseEventKey,caseRoleKey,caseRefundKey} from '@kuaixie/ui/useTradeCases';
import {api} from '../api/client';
import {uniEventValue} from '../utils/uniEvent';
const props=defineProps<{orderId?:string;caseId?:string;createOnly?:boolean}>();
const p=useTradeCases(api,async(title,content)=>!!(await uni.showModal({title,content})).confirm);
function index(e:unknown){return Number(uniEventValue(e))}
watch(()=>props.orderId,value=>{if(value)p.draft.orderId=value},{immediate:true});
watch(()=>props.caseId,value=>{if(value)void p.loadDetail(value)},{immediate:true});
onMounted(()=>{void p.loadList();void p.loadOrders()});
</script>
<template><view class="trade-cases"><view class="op-title">{{t('case.title')}}</view><view class="v15-notice">{{t('case.financialNotice')}}</view><view v-if="p.error.value" class="op-error">{{p.error.value}}</view><view v-if="p.loading.value" class="op-empty">{{t('account.loading')}}</view><button :disabled="p.loading.value||!!p.pending.value" @click="p.loadList()">{{t('case.refresh')}}</button><view v-for="row in p.rows.value" :key="row.id" class="op-card"><button :disabled="!!p.pending.value" @click="p.loadDetail(row.id)">{{row.order_no||row.order_id}} · {{t(caseStageKey(row.stage))}}</button></view><view v-if="!p.rows.value.length&&!p.loading.value" class="op-empty">{{t('case.noCases')}}</view><button v-if="p.more.value" @click="p.loadList(true)">{{t('case.more')}}</button>
<view v-if="!caseId" class="op-card"><view class="op-card-title">{{t('v15.disputeCreate')}}</view><picker :disabled="!!p.pending.value" :range="p.orders.value.map(o=>(o.order_no||o.id)+' · '+o.item_name)" @change="p.draft.orderId=p.orders.value[index($event)]?.id||''"><view class="v15-selector">{{p.order.value?.order_no||p.draft.orderId||t('case.selectOrder')}} ⌄</view></picker><button v-if="p.moreOrders.value" @click="p.loadOrders(true)">{{t('case.more')}}</button><picker :disabled="!!p.pending.value" :range="caseTypes.map(v=>t(caseTypeKey(v)))" @change="p.draft.type=caseTypes[index($event)]||'quality'"><view class="v15-selector">{{t(caseTypeKey(p.draft.type))}} ⌄</view></picker><textarea v-model="p.draft.description" :disabled="!!p.pending.value" maxlength="4000" :placeholder="t('v15.description')" class="v15-area"/><picker :disabled="!!p.pending.value" :range="caseResolutions.map(v=>t(caseOutcomeKey(v)))" @change="p.draft.expectResolution=caseResolutions[index($event)]||'refund_part'"><view class="v15-selector">{{t(caseOutcomeKey(p.draft.expectResolution))}} ⌄</view></picker><input v-if="['refund_part','compensate'].includes(p.draft.expectResolution)" v-model="p.draft.amount" :disabled="!!p.pending.value" type="digit" :placeholder="t('v15.refundAmount')" class="v15-field"/><text>{{t('case.evidence')}}</text><textarea v-model="p.draft.evidence" :disabled="!!p.pending.value" maxlength="4100" class="v15-area"/><view class="op-muted">{{t('case.evidenceHint')}}</view><button :disabled="p.busy.value||!!p.pending.value" @click="p.create()">{{t('v15.submit')}}</button></view>
<view v-if="p.entry.value" class="op-card"><button :disabled="p.loading.value||!!p.pending.value" @click="p.loadDetail(p.entry.value.id)">{{t('v15.refresh')}}</button><view class="op-card-title">{{p.entry.value.order_no||p.entry.value.order_id}} · {{t(caseStageKey(p.entry.value.stage))}}</view><view>{{t(caseRoleKey(p.entry.value.myRole))}} · {{t('case.round')}} {{p.entry.value.round}}</view><view class="v14-body">{{p.entry.value.description}}</view><view v-if="p.entry.value.negotiation_deadline">{{t('case.deadline')}}: {{formatDate(p.entry.value.negotiation_deadline)}}</view><view v-if="p.entry.value.respondent_note">{{p.entry.value.respondent_note}}</view><view v-if="p.entry.value.refund_amount!=null">{{t('v15.refundAmount')}}: {{formatAmount(p.entry.value.refund_amount,'CNY')}}</view><view v-if="p.entry.value.verdict">{{t(caseOutcomeKey(p.entry.value.verdict))}} · {{p.entry.value.verdict_reason}}</view><view v-if="p.entry.value.refund_status">{{t(caseRefundKey(p.entry.value.refund_status))}}</view><view v-if="p.entry.value.resolved_at">{{formatDate(p.entry.value.resolved_at)}}</view><text v-for="url in [...p.entry.value.evidence_urls,...p.entry.value.respondent_evidence_urls]" :key="url" selectable>{{url}}</text><textarea v-model="p.note.value" :disabled="!!p.pending.value" maxlength="1000" :placeholder="t('case.note')" class="v15-area"/><text>{{t('case.evidence')}}</text><textarea v-model="p.evidence.value" :disabled="!!p.pending.value" maxlength="4100" class="v15-area"/><button v-if="['negotiating','platform_review','appeal','awaiting_refund','awaiting_fulfilment'].includes(p.entry.value.stage)" :disabled="p.busy.value||!!p.pending.value" @click="p.act('respond')">{{t('case.responded')}}</button><button v-if="p.entry.value.stage==='negotiating'" :disabled="p.busy.value||!!p.pending.value" @click="p.act('escalate')">{{t('case.escalated')}}</button><button v-if="!p.entry.value.reopened_used&&['resolved','awaiting_refund','awaiting_fulfilment'].includes(p.entry.value.stage)" :disabled="p.busy.value||!!p.pending.value" @click="p.act('appeal')">{{t('case.appealed')}}</button><button v-if="p.entry.value.myRole==='buyer'&&p.entry.value.stage==='awaiting_fulfilment'" :disabled="p.busy.value||!!p.pending.value" @click="p.act('finish')">{{t('case.fulfilled')}}</button><view class="op-card-title">{{t('case.history')}}</view><view v-for="event in p.entry.value.events" :key="event.id" class="op-card"><view>{{t(caseEventKey(event.action))}} · {{t(caseRoleKey(event.actor_role))}}</view><text class="op-muted">{{formatDate(event.created_at)}}</text><view>{{event.payload.input.note||event.payload.input.reason||event.payload.input.description}}</view><text v-for="url in event.payload.input.evidenceUrls||[]" :key="url" selectable>{{url}}</text></view><button v-if="p.moreEvents.value" @click="p.history()">{{t('case.more')}}</button></view><button v-if="p.pending.value" :disabled="p.busy.value" @click="p.retry()">{{t('case.retryPending')}}</button></view></template>
<style scoped>.trade-cases{padding:16px}.trade-cases button{margin:10px 0}.trade-cases textarea{width:100%;box-sizing:border-box}.trade-cases text{display:block;overflow-wrap:anywhere}</style>
